'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const {createHash}=require('node:crypto');
const root=path.resolve(__dirname,'..'), id='319d90e8-416b-4a02-9e2c-0a91b50b4120';
const output=fs.mkdtempSync(path.join(root,'.workbuddy','p2-time-random-'+id+'-'));
const reportPath=path.join(output,'report.json'),hash=b=>createHash('sha256').update(b).digest('hex');
const result={status:'running',cases:[],errors:[],limitations:['固定种子只改变随机流，不冻结时钟、requestAnimationFrame、异步解码或资源。','同一任务同步截图只测试当前活动场景，不证明跨帧或异步稳定，也不证明双场景同尺度。','调用栈采样会增加开销和影响帧调度；按观察窗口汇总而非严格每帧调用计数。','资源数量稳定不证明资源内容、异步任务和 GPU 状态稳定。']};
function save(){fs.writeFileSync(reportPath,JSON.stringify(result,null,2));}
function once(s,a,b){const i=s.indexOf(a);if(i<0||s.indexOf(a,i+a.length)>=0)throw Error('替换点缺失或不唯一: '+a);return s.slice(0,i)+b+s.slice(i+a.length);}
async function build(){let b=fs.readFileSync(path.join(root,'build.mjs'),'utf8').replace(/\r\n/g,'\n');result.inputHashes=Object.fromEntries(['build.mjs','public/index.html','public/js/app.js','tools/test-deep-models.cjs'].map(f=>[f,hash(fs.readFileSync(path.join(root,f)))]));b=once(b,'const ROOT = path.dirname(fileURLToPath(import.meta.url));',`const ROOT = ${JSON.stringify(root)};`);b=once(b,"const app = read('js/app.js');",`const app = read('js/app.js').replace('window.__SE = {', 'window.__SE = { __timeProbe: {timeAtLg:cineTimeAtLg},');`);b=once(b,`for (const name of ['space.html', 'index.html']) {\n  fs.writeFileSync(path.join(ROOT, name), htmlOffline);\n}\nfs.writeFileSync(path.join(ROOT, 'space-http.html'), htmlHttp);`,`fs.writeFileSync(${JSON.stringify(path.join(output,'preview.html'))}, htmlOffline, {flag:'wx'});`);await import('data:text/javascript;base64,'+Buffer.from(b).toString('base64'));result.previewSha256=hash(fs.readFileSync(path.join(output,'preview.html')));}
async function run(){await build();const framework=path.join(root,'tools/test-deep-models.cjs');let s=fs.readFileSync(framework,'utf8');const cut=s.indexOf('async function main() {');if(cut<0)throw Error('驱动入口缺失');s=s.slice(0,cut).replace("const profile = fs.mkdtempSync(path.join(parent, 'probe-deep-models-'));", "const profile = fs.mkdtempSync(path.join(output, 'chrome-profile-'));");
const driver=`(async()=>{try{await launch();for(const mode of ['native','seeded']){if(mode==='seeded')await send('Page.addScriptToEvaluateOnNewDocument',{source:'(()=>{let x=0x13579bdf;Math.random=()=>{x^=x<<13;x^=x>>>17;x^=x<<5;x>>>=0;return x/4294967296}})()'});phase='加载 '+mode;await load(pathToFileURL(path.join(output,'preview.html')).href+'?auto=0&q=high','file');await evaluate('__SE.journey(0); true');for(const lg of [19.98,20.02]){phase=mode+' lg='+lg;await evaluate('__SE.journeySeek(__SE.__timeProbe.timeAtLg('+lg+'));true');await frames(3);for(const speed of [0,1]){await evaluate('__SE.ts='+speed+';true');await frames(2);await evaluate(\`(()=>{const orig=Math.random;window.__randomTrace={calls:0,stacks:{},start:performance.now(),date:Date.now()};Math.random=function(){const p=window.__randomTrace;p.calls++;const stack=(new Error()).stack.split(String.fromCharCode(10)).slice(2,7).map(x=>x.replace(/(?:file|blob):[^ )]+/g,'<preview>')).join(' | ');p.stacks[stack]=(p.stacks[stack]||0)+1;return orig();};window.__restoreRandom=()=>{Math.random=orig};return true})()\`);await frames(3);const observed=await evaluate(\`(()=>{const p=__randomTrace;__restoreRandom();const s=__SE,r=s.renderer;return {calls:p.calls,stacks:p.stacks,elapsed:performance.now()-p.start,dateElapsed:Date.now()-p.date,simSpeed:s.ts,journey:s.journeyInfo,resources:{geometries:r.info.memory.geometries,textures:r.info.memory.textures,programs:r.info.programs.length,resourceTimingEntries:performance.getEntriesByType('resource').length},contextLost:r.getContext().isContextLost()}})()\`);let shots;try{shots=await evaluate(\`(()=>{const a=__SE.snap('image/png',{gradePhase:0}),b=__SE.snap('image/png',{gradePhase:0});return {a,b,diagnostics:__SE.screenshotDiagnostics,clock:performance.now()}})()\`);const a=Buffer.from(shots.a.split(',')[1],'base64'),b=Buffer.from(shots.b.split(',')[1],'base64');shots={sha256a:hash(a),sha256b:hash(b),bytesA:a.length,bytesB:b.length,equal:a.equals(b),diagnostics:shots.diagnostics};}catch(e){shots={error:errorText(e)};result.errors.push({phase:phase+' 截图',error:errorText(e)});}result.cases.push({mode,lg,speed,observed,shots});save();}}}result.status=result.errors.length?'partial':'complete';}catch(e){result.status='failed';result.errors.push({phase,error:errorText(e)});}finally{result.browser=report.browser?{product:report.browser.product,jsVersion:report.browser.jsVersion}:null;result.driverErrors=report.errors.map(x=>({phase:x.phase,kind:x.kind}));if(browser){try{cleanupPromise=Promise.resolve();await browser.send('Browser.close');}catch(e){result.errors.push({phase:'关闭浏览器',error:String(e)});}browser.ws.close();}else if(child&&child.exitCode===null)child.kill();save();console.log(JSON.stringify({report:reportPath,status:result.status,cases:result.cases.length,errors:result.errors}));}})();`;
vm.runInThisContext(`(function(require,__dirname,__filename,process,Buffer,WebSocket,output,result,save,reportPath,hash){${s}\n${driver}\n})`,{filename:framework})(require,__dirname,framework,process,Buffer,WebSocket,output,result,save,reportPath,hash);}
save();run().catch(e=>{result.status='failed';result.errors.push({phase:'构建或驱动初始化',error:String(e)});save();console.error(JSON.stringify({report:reportPath,status:result.status,errors:result.errors}));process.exitCode=1;});
